SELECT 
  FROM mock_transaction
 WHERE profile_code = #{profileCode} AND account_num = #{accountNum}
   AND SUBSTRING(trans_dtime, 1, 8) BETWEEN #{fromDate} AND #{toDate}
 ORDER BY trans_dtime DESC, seq DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
  FROM mock_transaction
 WHERE profile_code = #{profileCode} AND account_num = #{accountNum}
   AND SUBSTRING(trans_dtime, 1, 8) BETWEEN #{fromDate} AND #{toDate}

SELECT 
  FROM mock_transaction
 WHERE profile_code = #{profileCode} AND account_num = #{accountNum}
 ORDER BY trans_dtime DESC, seq DESC
 LIMIT #{limit}

SELECT COUNT(*)
  FROM mock_transaction
 WHERE profile_code = #{profileCode} AND account_num = #{accountNum}
   AND SUBSTRING(trans_dtime, 1, 8) = #{dateStr}
